INSERT INTO `egc_email_template` (`sno`, `email_template_id`, `branch_id`, `email_name`, `email_subject`, `created_at`, `created_by`, `updated_at`, `updated_by`, `status`) VALUES
(1, 'ET-0001/25', 0, '🎉 EGC Login Credentials – Welcome to Elysium Groups', '<p>Dear <strong>#employee_name</strong>,</p><p>We hope you are excited to begin your journey with us at <strong>Elysium Groups of Company</strong>.</p><p> We are thrilled to welcome you as part of our growing professional family! 🤝✨</p><p>Below are your login credentials to access the <strong>EGC Employee Portal</strong>:</p><p>🔐 <strong>EGC Account Credentials</strong></p><p> 💼 Employee ID: #staffId</p><p> 👤 Username: #username</p><p> 🔑 Password: #password</p><p>🌐 <strong>Login Portal:</strong> #login_link</p><p>As a valued member of our team, you now join our collaborative network — proudly referred to as <strong>Elysium Mate</strong> 🤝😊</p><p>Should you face any difficulty or have questions, feel free to connect with us:</p><p>📞 <strong>HR Support:</strong> #hr_contact</p><p> 📧 <strong>Email:</strong> #hr_email</p><p>Once again, welcome aboard!</p><p> We look forward to growing and achieving great success together. 🌟</p><p>Warm Regards,</p><p> <strong>Team HR</strong></p><p> <strong>Elysium Groups of Company</strong></p><p> 🖥️ <em>www.elysiumgroup.com</em></p>', '2026-01-13 10:10:31', 0, '2026-01-13 10:10:31', 0, 0),
(2, 'ET-0002/25', 0, '#otp: Your Interview Verification Code - Elysium Groups', '<p><strong>Dear #employee_name,</strong></p><p><strong>Thank you for your interest in a career with Elysium Groups</strong>.</p><p>To proceed with your scheduled interview, please verify your identity using the One-Time Password (OTP) below:</p><h2><strong>#otp</strong></h2><p><em>This code is valid for </em><strong><em>30 minutes</em></strong><em>. For security reasons, do not share this code with anyone.</em></p><p><strong>Technical Support:</strong> If you did not request this code or are experiencing issues accessing the portal, please contact our talent acquisition team:</p><ul><li><strong>Email:</strong> #hr_email</li><li><strong>Support:</strong> #hr_contact</li></ul><p>We wish you the best of luck with your assessment.</p><p><strong>Team HR</strong> </p><p>Elysium Group of Companies </p><p>🖥️ <a href=\"http://www.elysiumgroups.com/\" rel=\"noopener noreferrer\" target=\"_blank\">www.elysiumgroups.com</a></p>', '2026-01-14 10:39:47', 0, '2026-01-14 10:39:47', 0, 0),
(3, 'ET-0003/26', 0, 'Interview Invitation – Elysium Groups', '<p>Dear #candidate_name,</p><p>Thank you for your interest in career opportunities with <strong>Elysium Group of Companies</strong>.</p><p>We are pleased to invite you to attend an online interview. Please find the interview details below and ensure you are available at the scheduled time.</p><p><strong>Interview Details</strong></p><p>Interview Type: #interview_type</p><p>Date: #interview_date</p><p><strong>Interview Access Link</strong></p><p>Kindly join the interview using the secure link below :</p><p>#interview_link</p><p><strong>Important Instructions:</strong></p><ul><li>Ensure you have a stable internet connection and are in a quiet environment.</li><li>Access the interview link from a secure device only.</li><li>Please do not share this interview link with anyone, as it is intended exclusively for you.</li></ul><p>If you did not expect this interview invitation or experience any technical difficulties while accessing the link, please contact our Talent Acquisition team for assistance.</p><p><strong>Technical Support / HR Contact:</strong></p><p>Email: #hr_email</p><p>Contact: #hr_contact</p><p>We look forward to connecting with you and wish you the very best.</p><p>Warm regards,</p><p><strong>Human Resources Team</strong></p><p>Elysium Groups</p><p>🖥️ <span style=\"color: rgb(0, 102, 204);\">www.elysiumgroups.com</span></p>', '2026-01-13 10:04:10', 0, '2026-01-13 10:04:10', 0, 0),
(4, 'ET-0004/26', 0, '#interview_type Invitation – Elysium Groups', '<p>Dear #candidate_name,</p><p>Thank you for your interest in career opportunities with <strong>Elysium Groups</strong>.</p><p>We are pleased to invite you to attend a <strong>#interview_type</strong> at our office. Please find the details below and plan your visit accordingly.</p><p><strong>Interview Details</strong></p><p>Interview Type: #interview_type</p><p>Date: #interview_date</p><p>Time: #interview_time</p><p>Venue: #interview_location</p><p><strong>Important Instructions:</strong></p><ul><li>Please arrive at the venue at least <strong>10 minutes prior</strong> to the scheduled time.</li><li>Carry a copy of your updated resume.</li><li>Formal or business-casual attire is recommended.</li></ul><p>If you are unable to attend on the mentioned date or require any clarification, please contact our Talent Acquisition team.</p><p><strong>Technical Support / HR Contact:</strong></p><p>Email: #hr_email</p><p>Contact: #hr_contact</p><p>We look forward to meeting you and wish you the very best.</p><p>Warm regards,</p><p><strong>Human Resources Team</strong></p><p>Elysium Groups</p><p>🖥️ <span style=\"color: rgb(0, 102, 204);\">www.elysiumgroups.com</span></p>', '2026-01-13 10:10:17', 0, '2026-01-13 10:10:17', 0, 0),
(5, 'ET-0005/26', 0, 'Congratulations – Selection Confirmation | Elysium Groups', '<p>Dear #candidate_name,</p><p>Congratulations!</p><p>We are pleased to inform you that you have been <strong>selected for the position of #job_title</strong> at <strong>Elysium Groups</strong>. After careful evaluation, we believe your skills, experience, and potential make you a strong fit for our organization.</p><p><strong>Selection &amp; Offer Details</strong></p><p>Position: #job_title</p><p>Work Location: #job_location</p><p>Joining Date: #joining_date</p><p>Next Step – Job Confirmation</p><p>To proceed further, we request you to <strong>confirm your acceptance of this offer</strong> by clicking the link below:</p><p>👉 <strong>Job Confirmation Link: </strong><a href=\" #job_confirmation_link\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 102, 204);\"><strong>click here</strong></a></p><p>Please complete the confirmation on or before <strong>#confirmation_deadline</strong>.</p><p>Important Notes:</p><ul><li>Upon confirmation, our HR team will share your detailed offer letter and onboarding instructions.</li><li>If you have any questions or require clarification regarding the role or terms, feel free to contact us.</li><li>Failure to confirm within the stipulated time may result in withdrawal of the offer.</li></ul><p>HR Contact Details:</p><p>Email: #hr_email</p><p>Contact: #hr_contact</p><p>We are excited about the possibility of you joining <strong>Elysium Groups</strong> and look forward to welcoming you to our team.</p><p>Once again, congratulations and best wishes for a successful career with us.</p><p>Warm regards,</p><p>Human Resources Team</p><p>Elysium Groups</p><p>🖥️<a href=\" www.elysiumgroups.com\" rel=\"noopener noreferrer\" target=\"_blank\"> </a><a href=\" www.elysiumgroups.com\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 102, 204);\">www.elysiumgroups.com</a></p>', '2026-01-21 10:01:55', 0, '2026-01-21 10:01:55', 0, 0),
(6, 'ET-0006/26', 0, 'Welcome Aboard! Your #com_name Application is Confirmed', '<p>Hi <strong>#name</strong>! 👋</p><p>Congratulations!</p><p>We are pleased to confirm that your application has been successfully submitted.</p><p><strong>Application Details:</strong></p><ul><li><strong>Application ID:</strong> #application_id</li><li><strong>Company:</strong> #company_name</li></ul><p>Our HR Recruitment Team will carefully review your registration and will reach out to you with the next steps soon.</p><p>Stay tuned for updates and get ready to explore exciting career opportunities with <strong>#company_name</strong>. 🚀</p><p>We are excited about your interest in joining our team and look forward to guiding you through the recruitment process.</p><p>Best regards,</p><p> <strong>HR Recruitment Team</strong></p><p> #company_name</p>', '2026-02-13 14:54:55', 0, '2026-02-13 14:54:55', 0, 0);
