INSERT INTO `egc_exam_guidelines` (`sno`, `exam_guidelines`, `created_by`, `created_at`, `updated_by`, `updated_at`, `status`) VALUES
(1, '<h3><u style=\"color: rgb(0, 102, 204);\">Guidelines to Online Examination</u></h3><ul><li><span style=\"color: rgb(0, 0, 0);\">Ensure stable and reliable internet connectivity throughout the examination duration.</span></li><li><span style=\"color: rgb(0, 0, 0);\">Close all unnecessary browsers and tabs before commencing the exam to ensure smooth functioning.</span></li><li><span style=\"color: rgb(0, 0, 0);\">Once the examination starts, avoid switching to any other window or tab. Such actions may be considered malpractice, leading to termination of the exam attempt.</span></li><li><span style=\"color: rgb(0, 0, 0);\">Staff Do not use the keyboard back button or close button/icon to navigate to previous pages or exit the exam screen.</span></li><li><span style=\"color: rgb(255, 77, 73);\">Staff will not be permitted to log in more than 30 minutes after the exam commencement time.</span></li><li><span style=\"color: rgb(0, 0, 0);\">Close all browsers/tabs before starting the online examination.</span></li></ul><h3><br></h3>', 0, '2025-08-12 15:03:37', 0, '2025-08-14 16:34:36', 0);
