INSERT INTO `egc_exam_questions` (`sno`, `branch_id`, `section_id`, `bank_id`, `case_study_check`, `case_study`, `option_type`, `question`, `option`, `option_answer`, `tips`, `explanation`, `created_by`, `created_at`, `updated_by`, `updated_at`, `status`) VALUES
(1, 1, 1, 1, 0, NULL, 0, 'When was PhDiZone established?', '[\"2000\",\"2005\",\"2010\",\"2015\"]', '[1]', 'Always start conversations by establishing credibility with our 20+ years of experience.', 'PhDiZone was established in 2005 as a subsidiary of Elysium Groups.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(2, 1, 1, 1, 0, NULL, 0, 'How many scholars has PhDiZone guided worldwide?', '[\"20,000+\",\"25,000+\",\"30,000+\",\"35,000+\"]', '[2]', 'Use this number to build trust: \'We\'ve successfully guided over 30,000 scholars worldwide.\'', 'This is a key credibility statistic that should be mentioned early in sales conversations.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(3, 1, 1, 1, 0, NULL, 0, 'What is PhDiZone\'s thesis defense success rate?', '[\"95%\",\"96%\",\"97%\",\"98%\"]', '[2]', 'Lead with this statistic: \'Before we dive in, you should know we have a 97% thesis defense success rate.\'', 'This is our primary success metric and strongest selling point.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(4, 1, 1, 1, 0, NULL, 0, 'PhDiZone is a subsidiary of which company?', '[\"Academic Solutions\",\"Research Experts\",\"Elysium Groups\",\"PhD Solutions\"]', '[2]', 'Mention this when discussing our stability and long-term support capabilities.', 'This establishes our institutional backing and credibility.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(5, 1, 1, 1, 0, NULL, 0, 'How many scholars does PhDiZone assist annually?', '[\"500+\",\"600+\",\"700+\",\"800+\"]', '[1]', 'Use this to demonstrate we\'re actively helping scholars, not just historical numbers.', 'This shows our current capacity and active engagement.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(6, 1, 1, 1, 0, NULL, 0, 'In how many countries does PhDiZone serve clients?', '[\"100+\",\"120+\",\"130+\",\"140+\"]', '[2]', 'Emphasize international experience when dealing with international students.', 'This demonstrates our global reach and experience with diverse academic systems.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(7, 1, 1, 1, 0, NULL, 0, 'How many PhD holders are on PhDiZone\'s expert team?', '[\"100+\",\"150+\",\"200+\",\"250+\"]', '[1]', 'Unlike general writing services, we only use PhD holders in your specific domain.', 'This differentiates us from services using general academic writers.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(8, 1, 1, 1, 0, NULL, 0, 'What is PhDiZone\'s on-time delivery rate?', '[\"96%\",\"97%\",\"98%\",\"99%\"]', '[2]', 'Use this when discussing timeline concerns or project management.', 'This addresses reliability concerns that PhD scholars often have.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(9, 1, 1, 1, 0, NULL, 0, 'How many research papers has PhDiZone helped publish?', '[\"18,000+\",\"20,000+\",\"21,000+\",\"23,000+\"]', '[2]', 'Mention this when discussing journal publication support services.', 'This shows our publication expertise beyond just thesis writing.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(10, 1, 1, 1, 0, NULL, 0, 'How many research institutes has PhDiZone collaborated with?', '[\"20+\",\"23+\",\"25+\",\"30+\"]', '[1]', 'Use this to show we understand academic standards and requirements.', 'This demonstrates institutional credibility and academic networking.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(11, 1, 1, 1, 0, NULL, 0, 'Which of the following is NOT a core service of PhDiZone?', '[\"Thesis Writing\",\"Journal Publication\",\"Career Placement\",\"Data Analysis\"]', '[2]', 'Stay focused on our core competencies during service discussions.', 'PhDiZone focuses on research support, not career placement services.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(12, 1, 1, 1, 0, NULL, 0, 'What is the fastest turnaround time for complete thesis?', '[\"25-35 days\",\"30-45 days\",\"45-60 days\",\"60-90 days\"]', '[1]', 'Use this for clients with tight deadlines, but emphasize quality isn\'t compromised.', 'This is our expedited service capability for urgent deadlines.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(13, 1, 1, 1, 0, NULL, 0, 'How many advanced technologies does PhDiZone integrate for research?', '[\"25+\",\"30+\",\"35+\",\"40+\"]', '[1]', 'Mention this when discussing technical or data-heavy research projects.', 'This shows our technological capabilities and modern approach.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(14, 1, 1, 1, 0, NULL, 0, 'What percentage of PhDiZone clients come from referrals?', '[\"50%\",\"55%\",\"60%\",\"65%\"]', '[2]', 'Use this as social proof: \'Interestingly, 60% of our clients come from referrals from successful scholars.\'', 'This demonstrates client satisfaction and trust in our services.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(15, 1, 1, 1, 0, NULL, 0, 'How many academic conferences does PhDiZone actively participate in?', '[\"125+\",\"130+\",\"135+\",\"140+\"]', '[2]', 'Demonstrates we stay current with academic trends and standards.', 'This shows our active engagement in the academic community.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(16, 1, 1, 1, 0, NULL, 0, 'What is PhDiZone\'s customer return rate?', '[\"75%\",\"80%\",\"85%\",\"90%\"]', '[1]', 'Many of our thesis clients also work with us for journal publications later.', 'This shows client satisfaction and repeat business.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(17, 1, 1, 1, 0, NULL, 0, 'How many research domains does PhDiZone support?', '[\"40+\",\"45+\",\"50+\",\"55+\"]', '[2]', 'Use this to assure clients we have expertise in their specific field.', 'This demonstrates our broad expertise across academic disciplines.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(18, 1, 1, 1, 0, NULL, 0, 'How many premium academic databases does PhDiZone have access to?', '[\"300+\",\"350+\",\"400+\",\"450+\"]', '[1]', 'Mention this when discussing literature review and research depth.', 'This shows our research capabilities and resource access.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(19, 1, 1, 1, 0, NULL, 0, 'What is the typical time saved on literature review with PhDiZone\'s structured approach?', '[\"50%\",\"60%\",\"70%\",\"80%\"]', '[1]', 'Use this when clients are struggling with literature review: \'Scholars reduce their literature review time by 60% with our structured approach.\'', 'This is a specific value proposition for literature review services.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(20, 1, 1, 1, 0, NULL, 0, 'How many global awards has PhDiZone received?', '[\"15+\",\"18+\",\"20+\",\"25+\"]', '[1]', 'Mention this when establishing credibility, especially with skeptical prospects.', 'This adds to our credibility and industry recognition.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(21, 1, 1, 1, 0, NULL, 0, 'How many helpdesk options does PhDiZone provide for customer support?', '[\"8+\",\"10+\",\"12+\",\"15+\"]', '[1]', 'Use this to address concerns about communication and support availability.', 'This shows our comprehensive support system.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(22, 1, 1, 1, 0, NULL, 0, 'What is PhDiZone\'s project success rate?', '[\"97%\",\"98%\",\"99%\",\"100%\"]', '[2]', 'Use this to build confidence in our ability to deliver successful outcomes.', 'This is our overall project completion success rate.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(23, 1, 1, 1, 0, NULL, 0, 'How many flexible payment options does PhDiZone offer?', '[\"15+\",\"18+\",\"20+\",\"25+\"]', '[1]', 'Mention this when discussing payment concerns or budget constraints.', 'This addresses budget and payment flexibility concerns.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(24, 1, 1, 1, 0, NULL, 0, 'What is the turnaround time for journal writing services?', '[\"15 days\",\"20 days\",\"25 days\",\"30 days\"]', '[1]', 'Use this when discussing publication deadlines and timelines.', 'This is our standard timeline for journal paper preparation.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(25, 1, 1, 1, 0, NULL, 0, 'How many industry events does PhDiZone present at annually?', '[\"45+\",\"49+\",\"55+\",\"60+\"]', '[1]', 'Demonstrates we\'re industry leaders, not just service providers.', 'This shows our active participation and thought leadership in the industry.', 1, '2025-08-29 15:10:11', 1, '2025-08-29 15:10:11', 0),
(26, 1, 2, 1, 0, NULL, 0, 'Which of the following is NOT a core service category of PhDiZone?', '[\"Research Services\",\"PhD Services\",\"University Admissions\",\"Development Services\"]', '[2]', 'Focus on the six core service categories to avoid confusion about scope.', 'PhDiZone\'s core services include Research, PhD, Add-On, Content, Development, and Analysis Services.', 1, '2025-08-29 15:22:55', 1, '2025-08-29 15:22:55', 0),
(27, 1, 2, 1, 0, NULL, 0, 'How many chapters are included in PhDiZone\'s standard thesis structure?', '[\"4 chapters\",\"5 chapters\",\"6 chapters\",\"7 chapters\"]', '[2]', 'Explain the comprehensive structure to show thoroughness of the service.', 'PhDiZone follows a standard 6-chapter thesis structure from Introduction to Conclusion.', 1, '2025-08-29 15:22:55', 1, '2025-08-29 15:22:55', 0),
(28, 1, 2, 1, 0, NULL, 0, 'What is the plagiarism threshold maintained by PhDiZone?', '[\"\\u22645%\",\"\\u22648%\",\"\\u226410%\",\"\\u226412%\"]', '[2]', 'Emphasize the strict plagiarism standards when discussing quality assurance.', 'PhDiZone maintains a plagiarism threshold of ≤10% verified by Turnitin/iThenticate.', 1, '2025-08-29 15:22:55', 1, '2025-08-29 15:22:55', 0),
(29, 1, 2, 1, 0, NULL, 0, 'Which programming languages does PhDiZone support for development services?', '[\"Java and Python only\",\"Java, Python, and MATLAB only\",\"Java, Python, MATLAB, VLSI, and Embedded Development\",\"All programming languages\"]', '[2]', 'Mention specific technical capabilities when dealing with engineering clients.', 'PhDiZone specifically supports Java, Python, MATLAB, VLSI, and Embedded Development.', 1, '2025-08-29 15:22:55', 1, '2025-08-29 15:22:55', 0),
(30, 1, 2, 1, 0, NULL, 0, 'Which statistical tools does PhDiZone use for data analysis?', '[\"SPSS only\",\"SPSS and R only\",\"SPSS, R, and Python only\",\"SPSS, R, STATA, SmartPLS, AMOS, Python\"]', '[3]', 'Match the statistical tool expertise to the client\'s specific research requirements.', 'PhDiZone supports multiple statistical analysis tools for diverse research needs.', 1, '2025-08-29 15:22:55', 1, '2025-08-29 15:22:55', 0),
(31, 1, 2, 1, 0, NULL, 0, 'What citation management tools does PhDiZone use?', '[\"EndNote only\",\"Mendeley and EndNote only\",\"Mendeley, EndNote, and Zotero\",\"All citation tools\"]', '[2]', 'Ask clients about their preferred citation tool and confirm compatibility.', 'PhDiZone supports the three major citation management platforms.', 1, '2025-08-29 15:22:55', 1, '2025-08-29 15:22:55', 0),
(32, 1, 2, 1, 0, NULL, 0, 'What is the standard document length range for thesis writing?', '[\"50-150 pages\",\"80-200 pages\",\"100-250+ pages\",\"150-300 pages\"]', '[2]', 'Clarify that length varies by university requirements and research scope.', 'Document length varies by discipline but typically ranges from 100-250+ pages.', 1, '2025-08-29 15:22:55', 1, '2025-08-29 15:22:55', 0),
