INSERT INTO `egc_skill_tag` (`sno`, `skill_tag_id`, `skill_tag_name`, `skill_tag_desc`, `created_by`, `created_at`, `updated_by`, `updated_at`, `status`) VALUES
(1, '', 'Java', 'A high-level, object-oriented programming language widely used for building web applications, mobile applications, and enterprise-level software.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(2, '', 'Core Java', 'Fundamental Java concepts such as classes, objects, data types, exception handling, collections, and multithreading.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(3, '', 'Advanced Java', 'Specialized areas of Java such as JDBC, JSP, Servlets, Spring, Hibernate, and Enterprise JavaBeans (EJB).', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(4, '', 'JavaScript', 'A high-level programming language used primarily for web development, enabling interactivity on websites and dynamic content creation.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(5, '', 'React.js', 'A JavaScript library used for building user interfaces, particularly single-page applications (SPA). It is component-based and allows for efficient updates.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(6, '', 'Node.js', 'An open-source, cross-platform JavaScript runtime environment used for server-side development. It uses event-driven, non-blocking I/O to build scalable applications.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(7, '', 'HTML5', 'The latest version of the HTML language used for structuring web pages and applications. Includes new elements for multimedia, graphics, and mobile device compatibility.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(8, '', 'CSS3', 'The latest version of Cascading Style Sheets (CSS) used for styling web pages, including animations, transitions, and responsive designs.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(9, '', 'SQL', 'Structured Query Language used for managing and manipulating relational databases. SQL is essential for tasks like querying, updating, and managing data.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(10, '', 'MySQL', 'An open-source relational database management system that uses SQL for managing and querying databases.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(11, '', 'MongoDB', 'A NoSQL database that stores data in flexible, JSON-like documents, making it scalable and easy to work with large sets of distributed data.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(12, '', 'Python', 'A high-level, interpreted programming language known for its simplicity and readability, widely used in web development, data science, and automation.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(13, '', 'Django', 'A high-level Python web framework that enables rapid development of secure and scalable web applications, following the model-template-views (MTV) architecture.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(14, '', 'Flask', 'A micro web framework written in Python used for building small to medium-sized web applications, known for its simplicity and flexibility.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(15, '', 'C++', 'A general-purpose programming language used in system software, game development, embedded systems, and high-performance computing.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(16, '', 'C#', 'A multi-paradigm, object-oriented programming language developed by Microsoft for building Windows applications, web applications, and game development using Unity.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(17, '', 'PHP', 'A server-side scripting language designed for web development but also used as a general-purpose programming language.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(18, '', 'Ruby on Rails', 'A full-stack web development framework written in Ruby, following the convention over configuration (CoC) and don\'t repeat yourself (DRY) principles.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(19, '', 'Swift', 'A powerful, fast, and interactive programming language used primarily for developing iOS and macOS applications.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(20, '', 'Kotlin', 'A statically-typed programming language that runs on the Java Virtual Machine (JVM) and is used primarily for Android app development.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(21, '', 'Android Development', 'The process of building applications for Android devices using Java, Kotlin, or other programming languages and tools like Android Studio.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(22, '', 'iOS Development', 'The process of building applications for Apple devices (iPhone, iPad) using Swift or Objective-C in Xcode.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(23, '', 'Git', 'A distributed version control system that allows developers to track changes in their codebase and collaborate effectively on projects.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(24, '', 'GitHub', 'A cloud-based platform for version control and collaboration that uses Git, enabling developers to host and review code, manage projects, and build software together.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(25, '', 'Docker', 'An open-source platform that allows developers to automate the deployment of applications inside lightweight, portable containers.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(26, '', 'Kubernetes', 'An open-source platform for automating the deployment, scaling, and management of containerized applications, commonly used in cloud-native architectures.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(27, '', 'AWS (Amazon Web Services)', 'A comprehensive, evolving cloud computing platform from Amazon offering infrastructure services like compute, storage, and databases.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(28, '', 'Azure', 'A cloud computing platform and service offered by Microsoft, providing computing, analytics, storage, and networking services.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(29, '', 'Google Cloud Platform (GCP)', 'A suite of cloud computing services from Google that offers compute power, storage, and machine learning tools for building applications and websites.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(30, '', 'Machine Learning', 'A branch of artificial intelligence (AI) that allows computers to learn from data and make decisions without explicit programming.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(31, '', 'Deep Learning', 'A subset of machine learning that uses artificial neural networks with many layers to analyze and interpret data at a higher level of abstraction.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(32, '', 'Data Science', 'The field of study that involves extracting knowledge and insights from structured and unstructured data using various methods, algorithms, and systems.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(33, '', 'Tableau', 'A data visualization tool used for transforming raw data into interactive and visual insights for business intelligence.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(34, '', 'Power BI', 'A business analytics tool from Microsoft that enables users to visualize data, share insights, and create reports and dashboards.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(35, '', 'Big Data', 'Large and complex data sets that require advanced tools and techniques, such as Hadoop and Spark, to process and analyze efficiently.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(36, '', 'Apache Hadoop', 'An open-source framework used for storing and processing large datasets in a distributed computing environment.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(37, '', 'Spark', 'An open-source, distributed computing system that provides an interface for programming entire clusters with implicit data parallelism and fault tolerance.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(38, '', 'Agile Methodology', 'A project management and software development methodology that emphasizes flexibility, collaboration, and iterative progress through small, incremental changes.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(39, '', 'Scrum', 'An Agile framework for managing complex projects, typically in software development, that emphasizes teamwork, accountability, and iterative progress.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(40, '', 'Project Management', 'The process of planning, organizing, and overseeing projects to ensure successful completion within scope, time, and cost constraints.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(41, '', 'Business Analysis', 'The practice of identifying business needs, analyzing requirements, and providing solutions to business problems through data and processes.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(42, '', 'Salesforce', 'A cloud-based customer relationship management (CRM) platform that helps businesses manage customer interactions, sales, and marketing efforts.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(43, '', 'SEO (Search Engine Optimization)', 'The process of optimizing a website or content to rank higher on search engine results pages to increase organic traffic.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(44, '', 'Digital Marketing', 'The promotion of products or brands through digital channels such as search engines, social media, email, and websites.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(45, '', 'Content Marketing', 'A strategy focused on creating and distributing valuable, relevant content to attract and retain a target audience.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(46, '', 'UI/UX Design', 'The design of user interfaces and user experiences for digital products to ensure a seamless, functional, and intuitive interaction.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(47, '', 'Adobe Photoshop', 'A powerful graphics editing software used for creating and manipulating images, widely used in photography, design, and digital art.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(48, '', 'Adobe Illustrator', 'A vector graphics editor used for creating scalable graphics like logos, illustrations, and diagrams.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(49, '', 'Video Editing', 'The process of editing and manipulating video footage to create a final product, typically using software like Adobe Premiere Pro or Final Cut Pro.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(50, '', 'Business Intelligence', 'Technologies and strategies used by companies for data analysis and reporting to improve decision-making and strategic planning.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(51, '', 'Network Security', 'The practice of protecting computer networks from unauthorized access, data breaches, and attacks using various technologies and protocols.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(52, '', 'Cybersecurity', 'The practice of defending computers, networks, and data from cyber threats like hacking, phishing, and malware attacks.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(53, '', 'Blockchain', 'A decentralized, distributed digital ledger technology that securely records transactions across multiple computers.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0),
(54, '', 'Cryptocurrency', 'A digital or virtual currency that uses cryptography for security and operates on decentralized blockchain networks.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:35:18', 2),
(55, '', 'Ethical Hacking', 'The practice of testing and securing systems by simulating attacks to find vulnerabilities that could be exploited by malicious hackers.', 0, '2025-03-21 12:25:43', 0, '2025-03-21 12:25:43', 0);
